'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { PACKAGES as initialPackages } from '@/data/mockData';

const PackageContext = createContext();

export const PackageProvider = ({ children }) => {
    const [packages, setPackages] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchPackages = async () => {
        setLoading(true);
        const { data, error } = await supabase
            .from('packages')
            .select('*')
            .order('created_at', { ascending: false });

        if (error) {
            console.error('Error fetching packages:', error);
        } else {
            setPackages(data || []);
        }
        setLoading(false);
    };

    useEffect(() => {
        fetchPackages();
    }, []);

    const addPackage = async (newPackage) => {
        const { data, error } = await supabase
            .from('packages')
            .insert([newPackage])
            .select();

        if (error) {
            console.error('Error adding package:', error);
            return { error };
        }
        if (data) {
            setPackages([data[0], ...packages]);
            return { data: data[0] };
        }
    };

    const updatePackage = async (id, updatedData) => {
        const { error } = await supabase
            .from('packages')
            .update(updatedData)
            .eq('id', id);

        if (error) {
            console.error('Error updating package:', error);
            return { error };
        }
        setPackages(packages.map(pkg => pkg.id === id ? { ...pkg, ...updatedData } : pkg));
        return { success: true };
    };

    const deletePackage = async (id) => {
        const { error } = await supabase
            .from('packages')
            .delete()
            .eq('id', id);

        if (error) {
            console.error('Error deleting package:', error);
            return { error };
        }
        setPackages(packages.filter(pkg => pkg.id !== id));
        return { success: true };
    };

    return (
        <PackageContext.Provider value={{ packages, loading, addPackage, updatePackage, deletePackage, refreshPackages: fetchPackages }}>
            {children}
        </PackageContext.Provider>
    );
};

export const usePackages = () => {
    const context = useContext(PackageContext);
    if (!context) {
        throw new Error('usePackages must be used within a PackageProvider');
    }
    return context;
};
